import numpy as np

def calculate_R(n):
    if n < 4:
        return None
    # f(K_n) = C(n, 3)
    f = n * (n - 1) * (n - 2) // 6
    # g(K_n) = C(n, 4)
    g = n * (n - 1) * (n - 2) * (n - 3) // 24

    if f == 0 or g == 0:
        return 0.0

    # R(K_n) = g(K_n)^3 / f(K_n)^4
    return (g**3) / (f**4)

# Check the sequence for n=4 up to n=15
n_values = range(4, 16)
results = [(n, calculate_R(n)) for n in n_values]

print("n, R(K_n)")
for n, R_n in results:
    print(f"{n}, {R_n}")

# Check the limit using the derived closed form: R(n) = (3/32) * (n-3)^3 / (n(n-1)(n-2))
def closed_form_R(n):
    if n < 4:
        return None
    return (3/32) * ((n-3)**3) / (n * (n-1) * (n-2))

print("\nVerification (Closed Form) for n=15:", closed_form_R(15))
print("Limit check: (n-3)^3 / (n(n-1)(n-2)) approaches 1.")

